"""Cycles compute device selection for room renders. Run with Blender's Python."""

import os

import bpy


def select_device(scene):
    """Factory startup has no compute device preference; follow the scene's own CPU/GPU choice.

    A copy of select_device in packages/video/src/blender/resources/render_scene.py, which ships
    in a different resource tree; packages/video/test/blender.test.ts runs both.
    """
    if scene.cycles.device != "GPU":
        return "CPU (%d threads)" % os.cpu_count()
    preferences = bpy.context.preferences.addons["cycles"].preferences
    for backend in ("OPTIX", "CUDA", "HIP", "METAL", "ONEAPI"):
        try:
            preferences.compute_device_type = backend
        except TypeError:
            continue
        preferences.get_devices()
        devices = [d for d in preferences.devices if d.type == backend]
        if devices:
            for device in preferences.devices:
                device.use = device.type == backend
            return "%s: %s" % (backend, ", ".join(sorted({d.name for d in devices})))
    # The scene asks for a GPU this machine does not have: Blender falls back to the CPU.
    return "CPU fallback, no GPU found (%d threads)" % os.cpu_count()
